fn flip_case(s: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    for c in s {
        if c >= 'a' && c <= 'z' {
            // lowercase to uppercase by subtracting 32 in ASCII
            let upper = (c as u8 - 32) as char;
            result.push(upper);
        } else if c >= 'A' && c <= 'Z' {
            // uppercase to lowercase by adding 32 in ASCII
            let lower = (c as u8 + 32) as char;
            result.push(lower);
        } else {
            // other characters unchanged
            result.push(c);
        }
    }
    result
}